from .interface import rf_attenuator

import logging

__all__ = ['rf_attenuator']


def __getattr__(name):
    if name == "attenuator":
        logging.warning("Importing taf.hw.rf_attenuator.attenuator is deprecated. "
                        "Use taf.hw.rf_attenuator directly instead")
        return rf_attenuator

    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")


def __dir__():
    return __all__
